/* Real host + real Space panel. Owns windows; never injects physical input. */
#define COBJMACROS
#define wWinMain duplicate_unused_host_entrypoint
#include "../app/fpdemo.c"
#undef wWinMain
static int passed,failed;static wchar_t left[32768],right[32768];
#define CHECK(label,condition) do{if(condition){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static void pump_space(int ms){uint64_t end=GetTickCount64()+ms;do{MSG m;while(PeekMessageW(&m,NULL,0,0,PM_REMOVE))if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(2);}while(GetTickCount64()<end);}
static const wchar_t *space_test_name(Pane *p){return p->view&&p->cursor<p_count(p)?fpe_view_name(p->view,p->cursor):NULL;}
static int wait_space(void){uint64_t end=GetTickCount64()+15000;while(g_space_state==SP_RUNNING&&GetTickCount64()<end)pump_space(5);return g_space_state==SP_COMPLETE;}

static int wait_duplicates(void){uint64_t end=GetTickCount64()+30000;while((g_duplicate_state.state<4||!g_duplicate_state.generation)&&GetTickCount64()<end)pump_space(5);return g_duplicate_state.state==4;}
static void request_duplicate(uint64_t session,uint32_t generation,uint32_t root,uint32_t action,const wchar_t *relative){duplicate_action a={session,generation,root,action,0};size_t n=(wcslen(relative)+1)*2;uint8_t *p=malloc(sizeof a+n);memcpy(p,&a,sizeof a);memcpy(p+sizeof a,relative,n);panel_message(duplicate_app(),PANELP_DUPLICATE_ACTION,p,(uint32_t)(sizeof a+n));free(p);}
static void test_duplicate_host_roots_and_reuse(void){CHECK("ordinary browsing keeps duplicate helper dormant",!sidepanel_running(duplicate_app()));fn_ctx c;app_pane_ctx(&c,&g.panes[0],FN_FROM_CODE);c.n=c.dirs=0;c.state=FN_S_FOLDER;c.dir=left;CHECK("find command registered and applicable",fn_find("file.find_duplicates")&&fn_applies(fn_find("file.find_duplicates"),&c));fn_run(fn_find("file.find_duplicates"),&c);app_ctx_free(&c);CHECK("actual helper finishes frozen root",wait_duplicates()&&g_duplicate_request.count==1&&!wcscmp(g_duplicate_roots[0],left)&&g_duplicate_state.groups==1&&g_duplicate_state.members==2);uint64_t session=g_duplicate_request.session;uint32_t generation=sidepanel_generation(duplicate_app());p_navigate(&g.panes[0],right,NULL,1);pump_space(100);CHECK("navigation does not retarget scan",g_duplicate_request.session==session&&!wcscmp(g_duplicate_roots[0],left));sidepanel_close();pump_space(40);CHECK("hidden helper survives",sidepanel_running(duplicate_app()));pane_run(active_pane(),"duplicates.show",FN_FROM_CODE);pump_space(40);CHECK("show reuses authenticated helper results",sidepanel_open()&&sidepanel_generation(duplicate_app())==generation&&g_duplicate_request.session==session);}
static void test_duplicate_host_scoped_actions_and_preview(void){uint64_t session=g_duplicate_request.session,before=g.panes[1].nav_ticket;uint32_t generation=g_duplicate_state.generation;request_duplicate(session+1,generation,0,DUPLICATE_RIGHT,L"notes.md");request_duplicate(session,generation+1,0,DUPLICATE_RIGHT,L"notes.md");request_duplicate(session,generation,2,DUPLICATE_RIGHT,L"notes.md");request_duplicate(session,generation,0,DUPLICATE_RIGHT,L"..\\notes.md");request_duplicate(session,generation,0,DUPLICATE_RIGHT,L"notes.md:stream");CHECK("stale sessions, generations and root escapes refused",g.panes[1].nav_ticket==before);request_duplicate(session,generation,0,DUPLICATE_RIGHT,L"notes.md");uint64_t end=GetTickCount64()+7000;while((!g.panes[1].path||wcscmp(g.panes[1].path,left)||!space_test_name(&g.panes[1])||wcscmp(space_test_name(&g.panes[1]),L"notes.md"))&&GetTickCount64()<end)pump_space(5);CHECK("reveal right selects actual file",g.panes[1].path&&!wcscmp(g.panes[1].path,left)&&space_test_name(&g.panes[1])&&!wcscmp(space_test_name(&g.panes[1]),L"notes.md"));request_duplicate(session,generation,0,DUPLICATE_PREVIEW,L"notes.md");end=GetTickCount64()+7000;while(g.pv_shown!=3&&GetTickCount64()<end)pump_space(5);CHECK("duplicate preview uses real existing text reader",g.pv_shown==3&&IsWindowVisible(textview_window()));const wchar_t *roots[]={left,right};duplicate_open_roots(roots,2);CHECK("both pane roots accepted",wait_duplicates()&&g_duplicate_request.count==2&&g_duplicate_request.session!=session&&g_duplicate_state.groups==1&&g_duplicate_state.members==3);}
static void test_duplicate_host_disabled_feature_and_registry(void){const char *settings="[functions]\nfile.find_duplicates = off\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();pump_space(50);CHECK("disabling stops only duplicate helper",!fn_active(fn_find("file.find_duplicates"))&&!sidepanel_running(duplicate_app()));char report[65536];fn_report_csv(report,sizeof report);CHECK("no registry lifecycle violations",strstr(report,"metric,fn_violations,,,,0,")!=NULL);CHECK("new commands all fit registry",fn_find("duplicates.copy_path")&&fn_find("workspace.manage")&&fn_find("wsl.helper"));}
int wmain(int argc,wchar_t **argv){if(argc!=3)return 2;wcsncpy(left,argv[1],32767);wcsncpy(right,argv[2],32767);CoInitializeEx(NULL,COINIT_APARTMENTTHREADED);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);fn_host host={host_now,host_arm,host_status};fn_init(&host);fn_register(app_functions,sizeof app_functions/sizeof *app_functions);functions_register();relay_register();palette_register();const char *settings="[functions]\nsvc.shell = off\nsvc.icons = off\n[panel.side]\nslide = off\n";fn_settings(settings,strlen(settings));fn_configure_all();g.engine=fpe_engine_create(NULL);g.dual=1;g.ratio=0.5;session_defaults(&g_ses);for(int i=0;i<2;i++){Pane *p=&g.panes[i];p->idx=i;p->ntabs=1;p->drop_row=-1;p->opts.dirs_first=1;}HINSTANCE instance=GetModuleHandleW(NULL);register_class(L"OpenPilot",main_proc,0,instance);register_class(L"OpenPilotPane",pane_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotTree",tree_proc,CS_DBLCLKS,instance);register_class(L"OpenPilotDebug",dbg_proc,0,instance);HWND window=CreateWindowExW(0,L"OpenPilot",L"Owned Duplicate integration",WS_OVERLAPPEDWINDOW|WS_CLIPCHILDREN,80,80,1300,820,NULL,NULL,instance,NULL);if(!window)return 3;for(int i=0;i<2;i++){fpe_dir *dir=read_start(i?right:left);if(dir){p_show_dir(&g.panes[i],dir,NULL,0);fpe_dir_release(dir);}}ShowWindow(window,SW_SHOWNOACTIVATE);UpdateWindow(window);pump_space(20);test_duplicate_host_roots_and_reuse();test_duplicate_host_scoped_actions_and_preview();test_duplicate_host_disabled_feature_and_registry();DestroyWindow(window);pump_space(100);settings_save_join();folderwatch_join();fpe_engine_destroy(g.engine);free(g_space_root);CoUninitialize();printf("%d passed, %d failed; 3 duplicate host selectors\n",passed,failed);return failed?1:0;}
